# ---------------------------------------------------------------------------
# Overflow report
# ---------------------------------------------------------------------------
ISSUES = []


def issue(kind, where, detail):
    ISSUES.append((kind, where, detail))


def report_overflow():
    print(f"OVERFLOW REPORT: {len(ISSUES)} issue(s)")
    for kind, where, detail in ISSUES:
        print(f"  [{kind}] {where}: {detail}")
    return len(ISSUES)


# ---------------------------------------------------------------------------
# Pixel buffer + primitives
# ---------------------------------------------------------------------------
buf = bytearray(W * H * 3)


def set_px(x, y, color):
    if 0 <= x < W and 0 <= y < H:
        i = (y * W + x) * 3
        buf[i], buf[i + 1], buf[i + 2] = color


def fill_rect(x, y, w, h, color):
    x0, y0 = max(0, x), max(0, y)
    x1, y1 = min(W, x + w), min(H, y + h)
    for yy in range(y0, y1):
        base = yy * W * 3
        for xx in range(x0, x1):
            i = base + xx * 3
            buf[i], buf[i + 1], buf[i + 2] = color


def fill_circle(cx, cy, r, color):
    for yy in range(cy - r, cy + r + 1):
        dx = int(math.sqrt(max(0, r * r - (yy - cy) * (yy - cy))))
        for xx in range(cx - dx, cx + dx + 1):
            set_px(xx, yy, color)


def draw_line(x0, y0, x1, y1, color):
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    while True:
        set_px(x0, y0, color)
        if x0 == x1 and y0 == y1:
            break
        e2 = 2 * err
        if e2 >= dy:
            err += dy
            x0 += sx
        if e2 <= dx:
            err += dx
            y0 += sy


def fill_triangle(x1, y1, x2, y2, x3, y3, color):
    pts = sorted([(x1, y1), (x2, y2), (x3, y3)], key=lambda p: p[1])
    (ax, ay), (bx, by), (cx, cy) = pts
    for y in range(ay, cy + 1):
        if y < by:
            t1 = 0.0 if by == ay else (y - ay) / (by - ay)
            xa = ax + (bx - ax) * t1
        else:
            t1 = 0.0 if cy == by else (y - by) / (cy - by)
            xa = bx + (cx - bx) * t1
        t2 = 0.0 if cy == ay else (y - ay) / (cy - ay)
        xb = ax + (cx - ax) * t2
        lo, hi = (int(xa), int(xb)) if xa <= xb else (int(xb), int(xa))
        for x in range(lo, hi + 1):
            set_px(x, y, color)


def hline(x, y, w, color, t=1):
    fill_rect(x, y, w, t, color)


def vline(x, y, h, color, t=1):
    fill_rect(x, y, t, h, color)


def box(x, y, w, h, color, t=1):
    hline(x, y, w, color, t)
    hline(x, y + h - t, w, color, t)
    vline(x, y, h, color, t)
    vline(x + w - t, y, h, color, t)


# ---------------------------------------------------------------------------
# Text engine: same tables measure and draw. Baseline-based.
# ---------------------------------------------------------------------------
def font_metrics(table):
    """(ascent, descent) in px for a table: ascent above baseline, descent below."""
    asc, desc = 0, 0
    for ch, g in table.items():
        _adv, yoff, rows = g
        if not rows:
            continue
        asc = max(asc, -yoff)
        desc = max(desc, yoff + len(rows))
    return asc, desc


def text_w(table, text, where=""):
    w = 0
    for ch in text:
        g = table.get(ch)
        if g is None:
            issue("MISSING GLYPH", where, f"char {ch!r} not in font table")
            g = table[" "]
        w += g[0]
    return w


def draw_text(x, baseline, text, table, color, where=""):
    """Draw text with baseline at y=baseline. Returns x after last glyph."""
    cx = x
    for ch in text:
        g = table.get(ch)
        if g is None:
            issue("MISSING GLYPH", where, f"char {ch!r} not in font table")
            g = table[" "]
        adv, yoff, rows = g
        for r, row in enumerate(rows):
            yy = baseline + yoff + r
            for c, v in enumerate(row):
                if v == "#":
                    set_px(cx + c, yy, color)
        cx += adv
    return cx


def draw_text_centered(cx, baseline, text, table, color, where=""):
    w = text_w(table, text, where)
    return draw_text(cx - w // 2, baseline, text, table, color, where)


def wrap_lines(text, table, max_w, where=""):
    """Greedy word wrap. Returns list of lines; flags a word wider than max_w."""
    words = text.split(" ")
    lines, cur = [], ""
    for word in words:
        trial = word if not cur else cur + " " + word
        if text_w(table, trial, where) <= max_w or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    for ln in lines:
        if text_w(table, ln, where) > max_w:
            issue("OVER-WIDE", where,
                  f"line {ln!r} needs {text_w(table, ln, where)}px, have {max_w}px")
    return lines


def draw_para(x, top, text, table, color, max_w, line_h, max_lines=None,
              where=""):
    """Draw wrapped paragraph starting at top; returns the ink bottom (last
    baseline + descent) of the last line drawn. Flags over-tall when lines
    exceed max_lines."""
    lines = wrap_lines(text, table, max_w, where)
    if max_lines is not None and len(lines) > max_lines:
        issue("OVER-TALL", where,
              f"needs {len(lines)} lines, max {max_lines}: {lines[max_lines:]}")
        lines = lines[:max_lines]
    asc, desc = font_metrics(table)
    y = top
    last_baseline = None
    for ln in lines:
        last_baseline = y + asc
        draw_text(x, last_baseline, ln, table, color, where)
        y += line_h
    if last_baseline is None:
        return top
    return last_baseline + desc

