def draw_chip_bars(x, y, w, h):
    """Chips + rising bars (Nvidia)."""
    # chip: dark square with gold pins
    s = 44
    cx, cy = x + 8, y + (h - s) // 2
    fill_rect(cx, cy, s, s, NAVY)
    fill_rect(cx + 10, cy + 10, s - 20, s - 20, GOLD)
    for i in range(3):
        fill_rect(cx + 6 + i * 14, cy - 5, 6, 5, GOLD)
        fill_rect(cx + 6 + i * 14, cy + s, 6, 5, GOLD)
        fill_rect(cx - 5, cy + 6 + i * 14, 5, 6, GOLD)
        fill_rect(cx + s, cy + 6 + i * 14, 5, 6, GOLD)
    # rising bars
    bx = cx + s + 26
    base = y + h - 6
    for i, bh in enumerate((14, 26, 38)):
        fill_rect(bx + i * 24, base - bh, 16, bh, GREEN)
    draw_line(bx - 4, base - 42, bx + 66, base - 46, RED)


def draw_bank_doc(x, y, w, h):
    """Bank + proposed sanctions document (EU)."""
    # bank facade, left
    bx, by = x + 8, y + 4
    bw, bh = 110, h - 8
    fill_triangle(bx, by + 14, bx + bw // 2, by, bx + bw, by + 14, NAVY)
    fill_rect(bx, by + 14, bw, 4, NAVY)
    for i in range(3):
        fill_rect(bx + 8 + i * 34, by + 20, 10, bh - 28, NAVY)
    fill_rect(bx, by + bh - 6, bw, 6, NAVY)
    # document, right
    dx, dy = bx + bw + 18, y + 2
    dw, dh = w - (dx - x) - 8, h - 4
    fill_rect(dx, dy, dw, dh, (255, 255, 255))
    box(dx, dy, dw, dh, INK, 1)
    fill_triangle(dx + dw - 14, dy, dx + dw, dy + 14, dx + dw, dy, GREY)
    for i in range(3):
        fill_rect(dx + 10, dy + 10 + i * 8, dw - 30, 3, GREY)
    # PROPOSED stamp
    sw = text_w(FONT_S, "PROPOSED", "stamp")
    sx = dx + (dw - sw - 16) // 2
    sy = dy + dh - 22
    fill_rect(sx, sy, sw + 16, 18, RED)
    draw_text(sx + 8, sy + 13, "PROPOSED", FONT_S, PAPER, "stamp")


def draw_bridge_pylon(x, y, w, h):
    """Bridge (grants/rebuilding) + power pylon (credit/energy) (Nepal aid)."""
    # bridge, left
    bx, by = x + 6, y + 6
    bw, bh = 120, h - 12
    base = by + bh - 4
    draw_line(bx, base, bx + bw, base, RUST)
    for i in range(5):
        px = bx + 8 + i * 26
        draw_line(px, base, px, base - 12 - (10 if i in (1, 3) else 4), RUST)
    draw_line(bx, base - 12, bx + bw // 2, base - 26, RUST)
    draw_line(bx + bw // 2, base - 26, bx + bw, base - 12, RUST)
    # pylon, right
    px = bx + bw + 34
    top = y + 4
    bot = y + h - 4
    draw_line(px, top, px - 16, bot, NAVY)
    draw_line(px, top, px + 16, bot, NAVY)
    draw_line(px - 16, bot, px + 16, bot, NAVY)
    draw_line(px - 12, top + 12, px + 12, top + 12, NAVY)
    draw_line(px - 20, top + 6, px + 20, top + 6, NAVY)
    draw_line(px - 20, top + 6, px, top - 2, NAVY)
    draw_line(px + 20, top + 6, px, top - 2, NAVY)
    # lightning bolt (gold)
    fill_triangle(px + 30, top + 8, px + 38, top + 22, px + 32, top + 22, GOLD)
    fill_triangle(px + 32, top + 22, px + 40, top + 36, px + 34, top + 22, GOLD)


